CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS owner_recovery_tokens(token_hash text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE IF NOT EXISTS owners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), singleton boolean NOT NULL UNIQUE DEFAULT true CHECK(singleton), username text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agency_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id), data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO agency_settings(data) VALUES ('{"name":"AVX Studios","tagline":"Art • Visual • Experience","website":"https://avxstudios.netlify.app","currency":"INR","receiptPrefix":"AVX-RCP","invoicePrefix":"AVX-INV","quotePrefix":"AVX-QTE","footer":"Thank you for working with AVX Studios.","requestTimeoutMinutes":5,"sessionMinutes":60,"idleMinutes":15,"accent":"#ff002c","taxBps":0}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS service_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, color text NOT NULL DEFAULT '#a78bfa', active boolean NOT NULL DEFAULT true);
INSERT INTO service_categories(name,color) VALUES ('Video Editing','#ff4565'),('Website Development','#8b8cf8'),('Motion Graphics','#d3ad73'),('AI Video Production','#6db5a0'),('Branding & Design','#8cb8d9'),('Social Media Content','#bd8dbe'),('Other','#8d8992') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, company text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Active' CHECK(status IN('Lead','Active','Inactive','Archived')), profile jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), name text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Planning' CHECK(status IN('Planning','In Progress','Client Review','Revisions','Completed','On Hold','Cancelled')), priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN('Low','Medium','High','Urgent')), start_date date, deadline date, notes text NOT NULL DEFAULT '', completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_service_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), service_id uuid NOT NULL REFERENCES service_categories(id), description text NOT NULL, amount_paise bigint NOT NULL CHECK(amount_paise>0));
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid REFERENCES projects(id), title text NOT NULL, description text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN('Low','Medium','High','Urgent')), status text NOT NULL DEFAULT 'To Do' CHECK(status IN('To Do','In Progress','Completed')), due_date date, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deliverables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, url text NOT NULL, version text NOT NULL DEFAULT '1', delivered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN('invoice','quotation')), number text NOT NULL UNIQUE, client_id uuid NOT NULL REFERENCES clients(id), project_id uuid REFERENCES projects(id), status text NOT NULL CHECK(status IN('Draft','Issued','Voided','Accepted','Converted')), issue_date date NOT NULL, due_date date NOT NULL, subtotal_paise bigint NOT NULL CHECK(subtotal_paise>=0), discount_paise bigint NOT NULL CHECK(discount_paise>=0), tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000), tax_paise bigint NOT NULL CHECK(tax_paise>=0), total_paise bigint NOT NULL CHECK(total_paise>0), notes text NOT NULL DEFAULT '', terms text NOT NULL DEFAULT '', snapshot jsonb NOT NULL, pdf_base64 text NOT NULL, converted_project_id uuid REFERENCES projects(id), converted_invoice_id uuid REFERENCES documents(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id), service_id uuid NOT NULL REFERENCES service_categories(id), description text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), rate_paise bigint NOT NULL CHECK(rate_paise>=0), amount_paise bigint NOT NULL CHECK(amount_paise>=0));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key uuid NOT NULL UNIQUE, request_hash text NOT NULL, reference text NOT NULL UNIQUE, client_id uuid NOT NULL REFERENCES clients(id), project_id uuid NOT NULL REFERENCES projects(id), invoice_id uuid REFERENCES documents(id), amount_paise bigint NOT NULL CHECK(amount_paise>0), payment_date date NOT NULL, method text NOT NULL CHECK(method IN('UPI','Bank Transfer','Cash','Card','Other')), transaction_ref text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS payment_external_unique ON payments(method,lower(transaction_ref)) WHERE transaction_ref<>'';
CREATE TABLE IF NOT EXISTS payment_allocations(payment_id uuid NOT NULL REFERENCES payments(id), service_id uuid NOT NULL REFERENCES service_categories(id), amount_paise bigint NOT NULL CHECK(amount_paise>=0), PRIMARY KEY(payment_id,service_id));
CREATE TABLE IF NOT EXISTS refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), idempotency_key uuid NOT NULL UNIQUE, amount_paise bigint NOT NULL CHECK(amount_paise>0), refund_date date NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refund_allocations(refund_id uuid NOT NULL REFERENCES refunds(id), service_id uuid NOT NULL REFERENCES service_categories(id), amount_paise bigint NOT NULL CHECK(amount_paise>=0), PRIMARY KEY(refund_id,service_id));
CREATE TABLE IF NOT EXISTS receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL UNIQUE REFERENCES payments(id), number text NOT NULL UNIQUE, snapshot jsonb NOT NULL, pdf_base64 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, amount_paise bigint NOT NULL CHECK(amount_paise>0), expense_date date NOT NULL, category text NOT NULL, vendor text NOT NULL DEFAULT '', method text NOT NULL, project_id uuid REFERENCES projects(id), recurrence text NOT NULL DEFAULT 'None' CHECK(recurrence IN('None','Monthly','Yearly')), notes text NOT NULL DEFAULT '', voided_at timestamptz, void_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section text NOT NULL CHECK(section IN('clients','projects','payments','expenses')), record_id uuid NOT NULL, name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size BETWEEN 1 AND 5242880), content_base64 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section text NOT NULL, entity_id uuid, action text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS viewer_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, username text NOT NULL UNIQUE, password_hash text NOT NULL, status text NOT NULL DEFAULT 'Active' CHECK(status IN('Active','Disabled','Deleted')), expires_at timestamptz, last_login timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS viewer_permissions(viewer_id uuid NOT NULL REFERENCES viewer_accounts(id), section text NOT NULL CHECK(section IN('overview','clients','projects','tasks','payments','invoices','expenses','analytics')), PRIMARY KEY(viewer_id,section));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, owner_id uuid REFERENCES owners(id), viewer_id uuid REFERENCES viewer_accounts(id), status text NOT NULL CHECK(status IN('pending','approved','rejected','revoked','expired')), device text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, request_expires_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, last_activity_at timestamptz NOT NULL DEFAULT now(), idle_minutes integer NOT NULL DEFAULT 15, revoked_at timestamptz, CHECK((owner_id IS NULL)<>(viewer_id IS NULL)));
CREATE TABLE IF NOT EXISTS access_audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), viewer_id uuid REFERENCES viewer_accounts(id), session_id uuid REFERENCES sessions(id), event text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_limits(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS counters(key text PRIMARY KEY, value integer NOT NULL CHECK(value>0));
CREATE TABLE IF NOT EXISTS email_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_id uuid NOT NULL REFERENCES receipts(id), recipient text NOT NULL, provider_id text, status text NOT NULL CHECK(status IN('queued','accepted','failed')), error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_client_idx ON projects(client_id);
CREATE INDEX IF NOT EXISTS tasks_project_idx ON tasks(project_id);
CREATE INDEX IF NOT EXISTS documents_client_idx ON documents(client_id);
CREATE INDEX IF NOT EXISTS documents_project_idx ON documents(project_id);
CREATE INDEX IF NOT EXISTS payments_client_idx ON payments(client_id,payment_date);
CREATE INDEX IF NOT EXISTS payments_project_idx ON payments(project_id);
CREATE INDEX IF NOT EXISTS payments_invoice_idx ON payments(invoice_id);
CREATE INDEX IF NOT EXISTS payments_date_idx ON payments(payment_date);
CREATE INDEX IF NOT EXISTS refunds_payment_idx ON refunds(payment_id);
CREATE INDEX IF NOT EXISTS expenses_date_idx ON expenses(expense_date);
CREATE INDEX IF NOT EXISTS sessions_viewer_idx ON sessions(viewer_id,status);
CREATE INDEX IF NOT EXISTS sessions_pending_idx ON sessions(status,request_expires_at);
CREATE INDEX IF NOT EXISTS attachment_parent_idx ON attachments(section,record_id);
CREATE INDEX IF NOT EXISTS activity_entity_idx ON activity_logs(entity_id,created_at);
CREATE OR REPLACE FUNCTION prevent_financial_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial history is immutable; use audited reversal records'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payments','payment_allocations','refunds','refund_allocations','receipts','document_items','activity_logs','access_audit_logs'] LOOP
IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=t||'_immutable') THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_financial_mutation()',t||'_immutable',t); END IF;
END LOOP; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='avx_app') THEN CREATE ROLE avx_app NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='avx_readonly') THEN CREATE ROLE avx_readonly NOLOGIN; END IF; END $$;
GRANT USAGE ON SCHEMA public TO avx_readonly;
GRANT SELECT ON clients,projects,project_service_items,tasks,deliverables,documents,document_items,payments,payment_allocations,refunds,refund_allocations,receipts,expenses,service_categories,attachments,activity_logs TO avx_readonly;
GRANT USAGE ON SCHEMA public TO avx_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO avx_app;
REVOKE ALL ON schema_migrations FROM avx_app;
CREATE OR REPLACE FUNCTION avx_owner() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('avx.role',true),'')='owner' $$;
CREATE OR REPLACE FUNCTION avx_can(section_name text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT avx_owner() OR section_name=ANY(string_to_array(coalesce(current_setting('avx.sections',true),''),',')) $$;
DO $$ DECLARE t text; s text; BEGIN
FOR t,s IN SELECT * FROM (VALUES ('service_categories','overview'),('clients','clients'),('projects','projects'),('project_service_items','payments'),('tasks','tasks'),('deliverables','projects'),('documents','invoices'),('document_items','invoices'),('payments','payments'),('payment_allocations','payments'),('refunds','payments'),('refund_allocations','payments'),('receipts','invoices'),('expenses','expenses'),('agency_settings','settings'),('counters','settings'),('email_deliveries','settings')) AS rules(tbl,section_name) LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('DROP POLICY IF EXISTS business_read ON %I',t);
EXECUTE format('CREATE POLICY business_read ON %I FOR SELECT USING (avx_can(%L))',t,s);
EXECUTE format('DROP POLICY IF EXISTS owner_write ON %I',t);
EXECUTE format('CREATE POLICY owner_write ON %I FOR ALL USING (avx_owner()) WITH CHECK (avx_owner())',t);
END LOOP;
END $$;
ALTER TABLE attachments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS attachments_read ON attachments;
CREATE POLICY attachments_read ON attachments FOR SELECT USING(avx_owner());
DROP POLICY IF EXISTS attachments_write ON attachments;
CREATE POLICY attachments_write ON attachments FOR ALL USING(avx_owner()) WITH CHECK(avx_owner());
ALTER TABLE activity_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS activity_access ON activity_logs;
CREATE POLICY activity_access ON activity_logs FOR ALL USING(avx_owner()) WITH CHECK(avx_owner());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['documents','document_items','receipts'] LOOP
EXECUTE format('DROP POLICY IF EXISTS business_read ON %I',t);
EXECUTE format('CREATE POLICY business_read ON %I FOR SELECT USING (avx_owner() OR (avx_can(''invoices'') AND avx_can(''payments'') AND avx_can(''clients'') AND avx_can(''projects'')))',t);
END LOOP; END $$;
DROP POLICY IF EXISTS business_read ON service_categories;
CREATE POLICY business_read ON service_categories FOR SELECT USING (true);
INSERT INTO schema_migrations(version) VALUES(1),(2) ON CONFLICT DO NOTHING;
